using System; using System.IO; using System.Runtime.InteropServices; using System.Text;
class CredentialHelper { [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct CREDENTIAL{public uint Flags,Type;public string TargetName,Comment;public System.Runtime.InteropServices.ComTypes.FILETIME LastWritten;public uint CredentialBlobSize;public IntPtr CredentialBlob;public uint Persist,AttributeCount;public IntPtr Attributes;public string TargetAlias,UserName;} [DllImport("advapi32",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CredWrite(ref CREDENTIAL c,uint f); [DllImport("advapi32",CharSet=CharSet.Unicode)]static extern bool CredRead(string t,uint type,uint f,out IntPtr c);[DllImport("advapi32")]static extern void CredFree(IntPtr p);[DllImport("advapi32",CharSet=CharSet.Unicode)]static extern bool CredDelete(string t,uint type,uint f); static int Main(string[] a){if(a.Length<1)return 2;var target="PartnersInBiz/runtime/"+(a.Length>1?a[1]:"identity");if(a[0]=="put"){var b=Encoding.UTF8.GetBytes(Console.In.ReadToEnd());var p=Marshal.AllocHGlobal(b.Length);Marshal.Copy(b,0,p,b.Length);var c=new CREDENTIAL{Type=1,TargetName=target,CredentialBlobSize=(uint)b.Length,CredentialBlob=p,Persist=2,UserName="SYSTEM"};var ok=CredWrite(ref c,0);for(int i=0;i<b.Length;i++)b[i]=0;Marshal.ZeroFreeGlobalAllocUnicode(p);return ok?0:1;}if(a[0]=="get"){IntPtr p;if(!CredRead(target,1,0,out p))return 1;try{var c=Marshal.PtrToStructure<CREDENTIAL>(p);var b=new byte[c.CredentialBlobSize];Marshal.Copy(c.CredentialBlob,b,0,b.Length);Console.OpenStandardOutput().Write(b,0,b.Length);Array.Clear(b,0,b.Length);return 0;}finally{CredFree(p);}}if(a[0]=="clear")return CredDelete(target,1,0)?0:0;return 2;} }
